use super::*;
use crate::DomainError;
use proptest::prelude::*;

// Real git 2.43.0 output, generated by `testdata/diff-tree.sh` (`sh diff-tree.sh testdata`)
// in a temporary repo with `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1` and fixed dates.
// The command is always `git diff-tree` with the arguments of [`DIFF_TREE_ARGS`] and the revisions.

/// Root commit (`--root`): ten added files, among them `a\nbreak.txt`, `caf\xff.txt` (non-
/// UTF-8), `with space.txt` and `src/nested/deep.rs`.
const ROOT_COMMIT: &[u8] = include_bytes!("testdata/diff-tree-root.bin");
/// Relative to the parent: deleted, modified, exact rename, made executable, rename with
/// changes, added in a subfolder, file turned into a symbolic link.
const MIXED: &[u8] = include_bytes!("testdata/diff-tree-mixed.bin");
/// Copy of a file, with `-C --find-copies-harder` added.
const COPIES: &[u8] = include_bytes!("testdata/diff-tree-copies.bin");
/// Empty commit (`--allow-empty`): zero bytes.
const EMPTY: &[u8] = include_bytes!("testdata/diff-tree-empty.bin");
/// Merge compared with the first parent: only the file brought by the merged branch.
const MERGE: &[u8] = include_bytes!("testdata/diff-tree-merge.bin");
/// The script that generates the files: it must use the same arguments as [`DIFF_TREE_ARGS`].
const SCRIPT: &str = include_str!("testdata/diff-tree.sh");

const FILE: u32 = 0o100644;
const ZERO: Oid = Oid::from_bytes([0; Oid::LEN]);

fn oid(hex: &str) -> Oid {
    Oid::from_hex(hex.as_bytes()).expect("valid test oid")
}

fn parse(input: &[u8]) -> Vec<ChangedFile> {
    parse_diff_tree(input).expect("valid real output")
}

fn reason(err: DomainError) -> String {
    match err {
        DomainError::InvalidGitOutput { command, reason } => {
            assert_eq!(command, "diff-tree");
            reason
        }
        other => panic!("unexpected error: {other:?}"),
    }
}

fn paths(files: &[ChangedFile]) -> Vec<&[u8]> {
    files.iter().map(|f| f.path.as_bytes()).collect()
}

#[test]
fn the_script_uses_the_parser_arguments() {
    assert!(SCRIPT.contains(&format!(
        "git diff-tree {} \"$@\"",
        DIFF_TREE_ARGS.join(" ")
    )));
}

#[test]
fn root_commit_all_added() {
    let files = parse(ROOT_COMMIT);
    assert_eq!(
        paths(&files),
        [
            &b"a\nbreak.txt"[..],
            b"caf\xff.txt",
            b"deleted.txt",
            b"kind.txt",
            b"modified.txt",
            b"move.txt",
            b"old.txt",
            b"script.sh",
            b"src/nested/deep.rs",
            b"with space.txt",
        ]
    );
    for f in &files {
        assert_eq!(f.change, Change::Added, "{}", f.path);
        assert_eq!((f.old_mode, f.new_mode), (0, FILE));
        assert_eq!(f.old_oid, ZERO);
        assert_ne!(f.new_oid, ZERO);
        assert_eq!((&f.original, f.score), (&None, None));
        assert_eq!(f.old_path(), &f.path);
    }
    // The non-UTF-8 byte stays as it is; only the display replaces it.
    assert_eq!(files[1].path.to_str(), None);
    assert_eq!(files[1].path.to_string_lossy(), "caf\u{fffd}.txt");
    assert_eq!(
        files[4].new_oid,
        oid("b5660615986901aceae1450e10650892e191f8dc")
    );
}

#[test]
fn every_kind_of_change() {
    let files = parse(MIXED);
    let summary: Vec<_> = files
        .iter()
        .map(|f| {
            (
                f.change,
                f.original.as_ref().and_then(RepoPath::to_str),
                f.path.to_str().unwrap(),
                f.score,
            )
        })
        .collect();
    assert_eq!(
        summary,
        [
            (Change::Deleted, None, "deleted.txt", None),
            (Change::TypeChanged, None, "kind.txt", None),
            (Change::Modified, None, "modified.txt", None),
            (Change::Renamed, Some("move.txt"), "moved.txt", Some(87)),
            (Change::Renamed, Some("old.txt"), "new.txt", Some(100)),
            (Change::Modified, None, "script.sh", None),
            (Change::Added, None, "src/added.rs", None),
        ]
    );

    let deleted = &files[0];
    assert_eq!((deleted.old_mode, deleted.new_mode), (FILE, 0));
    assert_eq!(
        (deleted.old_oid, deleted.new_oid),
        (oid("3b1bafd0868f8236dbe5c12715e7536123af73f0"), ZERO)
    );

    let modified = &files[2];
    assert_eq!(
        (modified.old_oid, modified.new_oid),
        (
            oid("b5660615986901aceae1450e10650892e191f8dc"),
            oid("dfc6c23cce41711b6d943f056da4b5ae43ad0b6a")
        )
    );

    let exact = &files[4];
    assert_eq!(exact.old_oid, exact.new_oid);
    assert_eq!(exact.old_path().to_str(), Some("old.txt"));

    // Only the mode: same content, made executable.
    let script = &files[5];
    assert_eq!((script.old_mode, script.new_mode), (FILE, 0o100755));
    assert_eq!(script.old_oid, script.new_oid);

    let renamed = &files[3];
    assert_ne!(renamed.old_oid, renamed.new_oid);

    let link = &files[1];
    assert_eq!((link.old_mode, link.new_mode), (FILE, 0o120000));
    assert!(files.iter().all(|f| !f.is_submodule()));
}

#[test]
fn copy_with_two_paths() {
    let files = parse(COPIES);
    assert_eq!(files.len(), 1);
    let copy = &files[0];
    assert_eq!(copy.change, Change::Copied);
    assert_eq!(copy.score, Some(100));
    assert_eq!(
        copy.original.as_ref().and_then(RepoPath::to_str),
        Some("modified.txt")
    );
    assert_eq!(copy.path.to_str(), Some("copy.txt"));
}

#[test]
fn empty_commit_and_merge() {
    assert_eq!(EMPTY, b"");
    assert!(parse(EMPTY).is_empty());

    let files = parse(MERGE);
    assert_eq!(paths(&files), [b"side.txt"]);
    assert_eq!(files[0].change, Change::Added);
}

#[test]
fn submodule() {
    let input = b":000000 160000 0000000000000000000000000000000000000000 \
                  1111111111111111111111111111111111111111 A\0libs/sub\0";
    let files = parse(input);
    assert!(files[0].is_submodule());
    assert_eq!(files[0].new_mode, 0o160000);
}

#[test]
fn details_json() {
    let files = parse(MIXED);
    let value = serde_json::to_value(&files[3]).unwrap();
    assert_eq!(
        value,
        serde_json::json!({
            "path": "moved.txt",
            "change": "Renamed",
            "original": "move.txt",
            "score": 87,
            "old_mode": FILE,
            "new_mode": FILE,
            "old_oid": "5a1b55ef34f8b095d001a618d74a9e1aae5b9d28",
            "new_oid": "e03ad72246027463317c2ab1c13f673e0512d5be",
        })
    );
    let back: ChangedFile = serde_json::from_value(value).unwrap();
    assert_eq!(back, files[3]);
    // A non-UTF-8 path becomes a byte array and comes back identical.
    let latin = &parse(ROOT_COMMIT)[1];
    let value = serde_json::to_value(latin).unwrap();
    assert!(value["path"].is_array(), "{value}");
    assert_eq!(
        serde_json::from_value::<ChangedFile>(value).unwrap(),
        *latin
    );
}

#[test]
fn errors() {
    let header = ":100644 100644 913caa9051271045c0828025d3ce0d40ebbc9f95 \
                  5c296212396dfd8d045eb394ad827528451c02d2";
    let cases: &[(Vec<u8>, &str)] = &[
        (b"without nul".to_vec(), "does not end with NUL"),
        (format!("{header} M\0").into_bytes(), "missing path"),
        (format!("{header} M\0\0").into_bytes(), "empty path"),
        (
            format!("{header} R100\0a\0").into_bytes(),
            "missing destination path",
        ),
        (format!("{header} X\0a\0").into_bytes(), "status `X`"),
        (
            format!("{header} M50\0a\0").into_bytes(),
            "unexpected status `M50`",
        ),
        (format!("{header} R\0a\0b\0").into_bytes(), "score"),
        (format!("{header} R101\0a\0b\0").into_bytes(), "score"),
        (format!("{header} \0a\0").into_bytes(), "empty status"),
        (b"100644 M\0a\0".to_vec(), "must start with `:`"),
        (b":100644 M\0a\0".to_vec(), "2 fields instead of 5"),
        (
            b":100648 100644 913caa9051271045c0828025d3ce0d40ebbc9f95 \
              5c296212396dfd8d045eb394ad827528451c02d2 M\0a\0"
                .to_vec(),
            "octal mode",
        ),
        (
            b":100644 100644 xyz 5c296212396dfd8d045eb394ad827528451c02d2 M\0a\0".to_vec(),
            "old id",
        ),
    ];
    for (input, expected) in cases {
        let err = reason(parse_diff_tree(input).unwrap_err());
        assert!(err.contains(expected), "{expected}: {err}");
    }
    // The record number is that of the wrong record.
    let mut input = MIXED.to_vec();
    input.extend_from_slice(b":rotto\0x\0");
    let err = reason(parse_diff_tree(&input).unwrap_err());
    assert!(err.starts_with("record 8:"), "{err}");
}

proptest! {
    /// Any path without NUL comes back identical, even with newlines, spaces and non-UTF-8 bytes.
    #[test]
    fn arbitrary_paths(
        a in proptest::collection::vec(1u8..=255, 1..40),
        b in proptest::collection::vec(1u8..=255, 1..40),
    ) {
        let header = ":100644 100644 913caa9051271045c0828025d3ce0d40ebbc9f95 \
                      5c296212396dfd8d045eb394ad827528451c02d2";
        let mut input = format!("{header} R075\0").into_bytes();
        input.extend_from_slice(&a);
        input.push(0);
        input.extend_from_slice(&b);
        input.push(0);
        let files = parse_diff_tree(&input).unwrap();
        prop_assert_eq!(files.len(), 1);
        prop_assert_eq!(files[0].old_path().as_bytes(), &a[..]);
        prop_assert_eq!(files[0].path.as_bytes(), &b[..]);
    }

    /// No input makes the parser panic.
    #[test]
    fn never_panics(input in proptest::collection::vec(any::<u8>(), 0..200)) {
        let _ = parse_diff_tree(&input);
    }
}
